// ============================================================
// PhotonBoard — on-disk format of the offline fixture catalog
// (resources/fixture-library, generated by
// scripts/build-fixture-library.mjs, read by FixtureCatalog).
//
//   manifest.json          sources (repo, commit, license), stats
//   index.json.gz          CatalogIndexFile — everything search needs
//   fixtures/<shard>.json.gz  { [id]: FixtureDefinition } per manufacturer
//   LICENSES/              license texts of the source libraries
// ============================================================

import type { FixtureCatalogSource } from '../shared/types'

export const CATALOG_FORMAT = 1

/** [id, name, manufacturerIndex, categories, modes [[name, channelCount]…], source (0 = OFL, 1 = QLC+), shortName?] */
export type CatalogIndexRow = [string, string, number, string[], [string, number][], 0 | 1, string?]

export interface CatalogIndexFile {
  format: number
  /** Unified manufacturers (OFL + QLC+ spellings merged); `shard` = fixtures/<shard>.json.gz */
  manufacturers: { name: string; shard: string }[]
  fixtures: CatalogIndexRow[]
  /** Old / duplicate id → current id (OFL redirects, QLC+ fixtures superseded by OFL) */
  aliases: Record<string, string>
}

export interface CatalogManifestSource {
  id: FixtureCatalogSource
  name: string
  repository: string
  url: string
  revision: string
  date: string
  license: string
  licenseFile: string
  files: number
  converted: number
  fixtureCount: number
}

export interface CatalogManifest {
  format: number
  generatedBy: string
  fixtureCount: number
  manufacturerCount: number
  sources: CatalogManifestSource[]
  dedupePolicy: string
  duplicates: number
  skipped: { source: FixtureCatalogSource; path: string; reason: string }[]
}

export const CATALOG_SOURCE_CODES: Record<FixtureCatalogSource, 0 | 1> = { ofl: 0, qlcplus: 1 }
export const CATALOG_SOURCE_BY_CODE: FixtureCatalogSource[] = ['ofl', 'qlcplus']
